definition.html:
{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set rows = [] -%}
{%- for row in data if row is mapping and row.voucher_no and not row.is_total_row -%}
	{%- set ignore = rows.append(row) -%}
{%- endfor -%}
{{ rp.styles() }}
<div class="rpf">
	{%- if show_company %}{{ rp.company_header(filters.company) }}{% endif %}
	{%- if filters.include_payments %}
	{%- set entries = data | select("mapping") | rejectattr("is_total_row") | list %}
	{%- set opening = entries[0] if entries and not entries[0].voucher_no else None %}
	{%- set moves = entries | selectattr("voucher_no") | list %}
	{{ rp.head(_("Sales Register"), rp.period(filters.from_date, filters.to_date), ((moves[0].customer_name if moves else None) or filters.customer) | e) }}
	<table class="rpf-grid">
		<colgroup><col style="width: 80px"><col><col style="width: 140px"><col style="width: 112px"><col style="width: 112px"><col style="width: 128px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Voucher Type") }}</th>
				<th>{{ _("Voucher No.") }}</th>
				<th class="num">{{ _("Debit") }}</th>
				<th class="num">{{ _("Credit") }}</th>
				<th class="num">{{ _("Balance") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- if opening and (opening.debit or opening.credit or opening.balance) %}
			<tr>
				<td class="nowrap">{{ rp.date(filters.from_date) }}</td>
				<td>{{ _("Opening Balance") }}</td>
				<td></td>
				<td class="num">{{ rp.money(opening.debit) }}</td>
				<td class="num">{{ rp.money(opening.credit) }}</td>
				<td class="num">{{ rp.drcr(opening.balance) }}</td>
			</tr>
			{%- endif %}
			{%- set last = namespace(date=None) %}
			{%- for row in moves %}
			<tr>
				<td class="nowrap">{% if row.posting_date != last.date %}{{ rp.date(row.posting_date) }}{% endif %}</td>
				<td>{% if row.voucher_type == "Payment Entry" %}{{ _("Receipt") if row.credit else _("Payment") }}{% elif row.voucher_type == "Sales Invoice" %}{{ _("Credit Note") if row.debit < 0 else _("Sales") }}{% else %}{{ rp.vch_type(row) }}{% endif %}</td>
				<td class="nowrap muted">{{ row.voucher_no | e }}</td>
				<td class="num">{{ rp.money(row.debit) }}</td>
				<td class="num">{{ rp.money(row.credit) }}</td>
				<td class="num">{{ rp.drcr(row.balance) }}</td>
			</tr>
			{%- set last.date = row.posting_date %}
			{%- else %}
			<tr><td colspan="6" class="rpf-empty">{{ _("No transactions in this period") }}</td></tr>
			{%- endfor %}
			{%- if moves %}
			<tr class="total">
				<td></td>
				<td colspan="2">{{ _("Total") }}</td>
				<td class="num"><span class="double">{{ rp.money(moves | map(attribute="debit") | map("float") | sum) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(moves | map(attribute="credit") | map("float") | sum) }}</span></td>
				<td class="num">{{ rp.drcr(moves[-1].balance) }}</td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{%- else %}
	{{ rp.head(_("Sales Register"), rp.period(filters.from_date, filters.to_date)) }}
	<table class="rpf-grid">
		<colgroup><col style="width: 80px"><col style="width: 140px"><col><col style="width: 112px"><col style="width: 104px"><col style="width: 112px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Invoice No.") }}</th>
				<th>{{ _("Customer") }}</th>
				<th class="num">{{ _("Taxable Value") }}</th>
				<th class="num">{{ _("Tax") }}</th>
				<th class="num">{{ _("Invoice Total") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in rows %}
			<tr>
				<td class="nowrap">{{ rp.date(row.posting_date) }}</td>
				<td class="nowrap">{{ row.voucher_no | e }}</td>
				<td>
					{{ (row.customer_name or row.customer) | e }}
					{%- if row.tax_id %}<div class="note">{{ _("GSTIN") }} {{ row.tax_id | e }}</div>{% endif %}
				</td>
				<td class="num">{{ rp.money(row.net_total) }}</td>
				<td class="num">{{ rp.money(row.tax_total) }}</td>
				<td class="num">{{ rp.money(row.grand_total) }}</td>
			</tr>
			{%- else %}
			<tr><td colspan="6" class="rpf-empty">{{ _("No invoices in this period") }}</td></tr>
			{%- endfor %}
			{%- if rows %}
			<tr class="total">
				<td colspan="3">{{ _("Total") }} · {{ (_("{0} invoice") if rows | length == 1 else _("{0} invoices")).format(rows | length) }}</td>
				<td class="num"><span class="double">{{ rp.money(rows | map(attribute="net_total") | map("float") | sum) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(rows | map(attribute="tax_total") | map("float") | sum) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(rows | map(attribute="grand_total") | map("float") | sum) }}</span></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{%- endif %}
	{{ rp.footnote() }}
</div>

{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set parties = (filters.party if filters.party is sequence and filters.party is not string else [filters.party]) | select | list -%}
{%- set accounts = (filters.account if filters.account is sequence and filters.account is not string else [filters.account]) | select | list -%}
{%- set party = parties[0] if parties | length == 1 else None -%}
{%- set account = accounts[0] if accounts | length == 1 and not party else None -%}
{%- set account_type = frappe.db.get_value("Account", account, "account_type") if account else None -%}
{%- set single = party or account -%}
{%- set title = _("Bank Book") if account_type == "Bank" else (_("Cash Book") if account_type == "Cash" else (_("Statement of Account") if single else _("General Ledger"))) -%}
{%- set entries = [] -%}
{%- set totals = [] -%}
{%- for row in data if row is mapping and not row.is_total_row -%}
	{%- if row.voucher_no -%}{%- set ignore = entries.append(row) -%}{%- else -%}{%- set ignore = totals.append(row) -%}{%- endif -%}
{%- endfor -%}
{%- set opening = totals[0] if totals | length >= 3 else None -%}
{%- set closing = totals[-1] if totals else None -%}
{{ rp.styles() }}
<div class="rpf">
	{%- if show_company %}{{ rp.company_header(filters.company) }}{% endif %}
	{%- if party %}
	{{ rp.head(title, rp.period(filters.from_date, filters.to_date), rp.party_name(filters.party_type, party), rp.party_meta(filters.party_type, party)) }}
	{%- else %}
	{{ rp.head(title, rp.period(filters.from_date, filters.to_date), rp.short(account, filters.company) if account else None) }}
	{%- endif %}
	{%- if single %}
	<table class="rpf-grid">
		<colgroup><col style="width: 80px"><col><col style="width: 84px"><col style="width: 140px"><col style="width: 112px"><col style="width: 112px"><col style="width: 128px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Particulars") }}</th>
				<th>{{ _("Voucher Type") }}</th>
				<th>{{ _("Voucher No.") }}</th>
				<th class="num">{{ _("Debit") }}</th>
				<th class="num">{{ _("Credit") }}</th>
				<th class="num">{{ _("Balance") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- if opening and (opening.debit or opening.credit) %}
			<tr>
				<td class="nowrap">{{ rp.date(filters.from_date) }}</td>
				<td>{{ _("Opening Balance") }}</td>
				<td></td>
				<td></td>
				<td class="num">{{ rp.money(opening.debit) }}</td>
				<td class="num">{{ rp.money(opening.credit) }}</td>
				<td class="num">{{ rp.drcr(opening.balance) }}</td>
			</tr>
			{%- endif %}
			{%- set last = namespace(date=None) %}
			{%- for row in entries %}
			{%- set bill = (_("Bill") if (row.against_voucher or row.voucher_no) == row.voucher_no else _("Against Bill")) ~ " " ~ row.bill_no if row.bill_no else None %}
			{%- set narration = [bill, row.remarks if filters.show_remarks else None] | select | join("\n") %}
			<tr{% if narration %} class="has-narration"{% endif %}>
				<td class="nowrap">{% if row.posting_date != last.date %}{{ rp.date(row.posting_date) }}{% endif %}</td>
				<td>
					<span class="muted">{{ _("To") if row.debit else _("By") }}</span>
					{{ rp.short(row.against if (party or account) else (row.party or row.account), filters.company) }}
				</td>
				<td class="clip">{{ rp.vch_type(row) }}</td>
				<td class="nowrap muted">{{ row.voucher_no | e }}</td>
				<td class="num">{{ rp.money(row.debit) }}</td>
				<td class="num">{{ rp.money(row.credit) }}</td>
				<td class="num">{{ rp.drcr(row.balance) }}</td>
			</tr>
			{%- if narration %}
			<tr class="narration-row">
				<td></td>
				<td class="note narration">{{ narration | e }}</td>
				<td></td>
				<td></td>
				<td></td>
				<td></td>
				<td></td>
			</tr>
			{%- endif %}
			{%- set last.date = row.posting_date %}
			{%- else %}
			<tr><td colspan="7" class="rpf-empty">{{ _("No transactions in this period") }}</td></tr>
			{%- endfor %}
			{%- if closing %}
			{%- set grand = [closing.debit or 0, closing.credit or 0] | max %}
			<tr class="subtotal">
				<td></td>
				<td>{{ _("Total") }}</td>
				<td></td>
				<td></td>
				<td class="num">{{ rp.money(closing.debit) }}</td>
				<td class="num">{{ rp.money(closing.credit) }}</td>
				<td></td>
			</tr>
			<tr class="subtotal">
				<td></td>
				<td><span class="muted regular">{{ _("To") if closing.balance < 0 else _("By") }}</span> {{ _("Closing Balance") }}</td>
				<td></td>
				<td></td>
				<td class="num">{{ rp.money(-closing.balance) if closing.balance < 0 else "" }}</td>
				<td class="num">{{ rp.money(closing.balance) if closing.balance > 0 else "" }}</td>
				<td class="num">{{ rp.drcr(closing.balance) }}</td>
			</tr>
			<tr class="total">
				<td></td>
				<td></td>
				<td></td>
				<td></td>
				<td class="num"><span class="double">{{ rp.money(grand) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(grand) }}</span></td>
				<td></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{%- else %}
	{%- set vouchers = {} %}
	{%- set order = [] %}
	{%- for row in entries %}
	{%- set key = row.posting_date ~ "|" ~ row.voucher_type ~ "|" ~ row.voucher_no %}
	{%- if key not in vouchers %}
	{%- set ignore = vouchers.update({key: {"date": row.posting_date, "first": row, "legs": []}}) %}
	{%- set ignore = order.append(key) %}
	{%- endif %}
	{%- set ignore = vouchers[key]["legs"].append(row) %}
	{%- endfor %}
	<table class="rpf-grid rpf-vouchers">
		<colgroup><col style="width: 80px"><col><col style="width: 140px"><col style="width: 110px"><col style="width: 110px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Account") }}</th>
				<th>{{ _("Voucher") }}</th>
				<th class="num">{{ _("Debit") }}</th>
				<th class="num">{{ _("Credit") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for key in order %}
			{%- set voucher = vouchers[key] %}
			{%- for leg in voucher.legs | sort(attribute="credit") %}
			<tr class="{{ 'voucher' if loop.first else 'leg' }}">
				<td class="nowrap">{% if loop.first %}{{ rp.date(voucher.date) }}{% endif %}</td>
				<td>
					{{ rp.short(leg.account, filters.company) }}
					{%- if leg.party %} <span class="muted">· {{ (leg.party_name or leg.party) | e }}</span>{% endif %}
				</td>
				<td class="clip">
					{%- if loop.first %}{{ rp.vch_type(voucher.first) }}{% if loop.last %} <span class="muted">{{ voucher.first.voucher_no | e }}</span>{% endif %}
					{%- elif loop.index == 2 %}<span class="muted">{{ voucher.first.voucher_no | e }}</span>
					{%- if filters.show_remarks and voucher.first.remarks %}<div class="note narration">{{ voucher.first.remarks | e }}</div>{% endif %}
					{%- endif %}
				</td>
				<td class="num">{{ rp.money(leg.debit) }}</td>
				<td class="num">{{ rp.money(leg.credit) }}</td>
			</tr>
			{%- endfor %}
			{%- else %}
			<tr><td colspan="5" class="rpf-empty">{{ _("No transactions in this period") }}</td></tr>
			{%- endfor %}
			{%- if order %}
			<tr class="total">
				<td></td>
				<td colspan="2">{{ _("Total") }} · {{ (_("{0} voucher") if order | length == 1 else _("{0} vouchers")).format(order | length) }}</td>
				<td class="num"><span class="double">{{ rp.money(entries | map(attribute="debit") | map("float") | sum) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(entries | map(attribute="credit") | map("float") | sum) }}</span></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	<div class="rpf-meta rpf-caption">{{ _("Pick one party or one account in the report filters to print a ledger statement with running balance.") }}</div>
	{%- endif %}
	{{ rp.footnote() }}
</div>

{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set payable = report.report_name == "Accounts Payable" -%}
{%- set sign = -1 if payable else 1 -%}
{%- set rows = [] -%}
{%- for row in data if row is mapping and row.voucher_no and not row.is_total_row and row.outstanding -%}
	{%- set ignore = rows.append(row) -%}
{%- endfor -%}
{%- set parties = rows | map(attribute="party") | unique | list -%}
{%- set party_type = filters.party_type or (rows[0].party_type if rows else ("Supplier" if payable else "Customer")) -%}
{%- set as_on = rp.date(filters.report_date) -%}
{%- set company_name = frappe.db.get_value("Company", filters.company, "company_name") or filters.company -%}
{%- set party_fields = ["name", "primary_address", "tax_id"] -%}
{%- if frappe.get_meta(party_type).fields | selectattr("fieldname", "equalto", "gstin") | list -%}
	{%- set ignore = party_fields.append("gstin") -%}
{%- endif -%}
{%- set party_docs = {} -%}
{%- for doc in (frappe.get_all(party_type, filters={"name": ["in", parties]}, fields=party_fields) if parties else []) -%}
	{%- set ignore = party_docs.update({doc.name: doc}) -%}
{%- endfor -%}
{%- set currencies = rows | map(attribute="currency") | select | unique | list -%}
{%- set symbols = {} -%}
{%- for cur in (frappe.get_all("Currency", filters={"name": ["in", currencies]}, fields=["name", "symbol"]) if currencies else []) -%}
	{%- set ignore = symbols.update({cur.name: cur.symbol}) -%}
{%- endfor -%}
{%- set company_block = rp.company_header(filters.company) if show_company else "" -%}
{{ rp.styles("portrait") }}
<div class="rpf">
	{%- for party in parties %}
	{%- set party_rows = rows | selectattr("party", "equalto", party) | list %}
	{%- set balance = party_rows | map(attribute="outstanding") | map("float") | sum %}
	{%- set currency = party_rows[0].currency %}
	{%- set doc = party_docs.get(party) or {} %}
	<div class="rpf-page">
		{{ company_block }}
		<table class="rpf-layout">
			<tr>
				<td class="muted">{{ _("Ref") }}: {{ _("Balance Confirmation") }} / {{ party | e }}</td>
				<td class="align-right">{{ rp.date(frappe.utils.today()) }}</td>
			</tr>
		</table>
		<div class="rpf-address">
			{{ _("To") }},<br>
			<b>{{ (party_rows[0].supplier_name or party_rows[0].customer_name or party) | e }}</b><br>
			{%- if doc.primary_address %}{{ doc.primary_address | replace("<br>", ", ") | striptags | trim(", ") | e }}<br>{% endif %}
			{%- if doc.gstin or doc.tax_id %}{{ _("GSTIN") }} {{ (doc.gstin or doc.tax_id) | e }}{% endif %}
		</div>
		<p class="rpf-subject-line"><b>{{ _("Subject: Confirmation of balance as on {0}").format(as_on) }}</b></p>
		<p>{{ _("Dear Sir/Madam,") }}</p>
		<p>
			{{ _("As per our books of account, the balance in your account as on {0} is {1} {2} ({3}).").format(
				"<b>" ~ as_on ~ "</b>",
				"<b>" ~ frappe.utils.fmt_money(balance | abs, currency=currency),
				(_("Dr") if sign * balance > 0 else _("Cr")) ~ "</b>",
				frappe.utils.money_in_words(balance | abs, currency)
			) }}
			{%- if (balance > 0) == payable %} {{ _("This amount is payable by us to you.") }}
			{%- else %} {{ _("This amount is receivable by us from you.") }}{% endif %}
		</p>
		<p>{{ _("Please confirm this balance by {0}. If it does not agree with your books, please send us your statement of account for the period so that we can reconcile the difference.").format(rp.date(frappe.utils.add_days(frappe.utils.today(), 15))) }}</p>
		<p>{{ _("The list of pending bills is given below.") }}</p>
		<table class="rpf-layout rpf-sign">
			<tr>
				<td class="half">
					<div class="rpf-box rpf-reply">
						<div class="rpf-label">{{ _("Your confirmation") }}</div>
						<div class="rpf-reply-options">
							&#9744; {{ _("We confirm the above balance.") }}<br>
							&#9744; {{ _("Our books show {0} ________________ Dr / Cr.").format(symbols.get(currency) or currency) }}
						</div>
						<div class="rpf-label rpf-sign-line">{{ _("Signature, name and stamp") }}</div>
					</div>
				</td>
				<td class="half align-right">
					<div>{{ _("For {0}").format(company_name | e) }}</div>
					<div class="rpf-label rpf-signatory">{{ _("Authorised Signatory") }}</div>
				</td>
			</tr>
		</table>
		<div class="rpf-title rpf-section-title">{{ _("Pending bills as on {0}").format(as_on) }}</div>
		<table class="rpf-grid">
			<colgroup><col style="width: 80px"><col><col style="width: 80px"><col style="width: 128px"></colgroup>
			<thead>
				<tr>
					<th>{{ _("Date") }}</th>
					<th>{{ _("Reference No.") }}</th>
					<th>{{ _("Due On") }}</th>
					<th class="num">{{ _("Pending Amount") }}</th>
				</tr>
			</thead>
			<tbody>
				{%- for row in party_rows %}
				<tr>
					<td class="nowrap">{{ rp.date(row.posting_date) }}</td>
					<td>{{ (row.bill_no or row.voucher_no) | e }}</td>
					<td class="nowrap">{{ rp.date(row.due_date) }}</td>
					<td class="num">{{ rp.drcr(sign * row.outstanding) }}</td>
				</tr>
				{%- endfor %}
				<tr class="total">
					<td></td>
					<td>{{ _("Total") }}</td>
					<td></td>
					<td class="num"><span class="double">{{ rp.drcr(sign * balance) }}</span></td>
				</tr>
			</tbody>
		</table>
		{{ rp.footnote() }}
	</div>
	{%- else %}
	<div class="rpf-empty">{{ _("No pending balance to confirm") }}</div>
	{%- endfor %}
</div>

{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set payable = report.report_name == "Accounts Payable" -%}
{%- set sign = -1 if payable else 1 -%}
{%- set by_due_date = (filters.ageing_based_on or "Due Date") == "Due Date" -%}
{%- set rows = [] -%}
{%- for row in data if row is mapping and row.voucher_no and not row.is_total_row and row.outstanding -%}
	{%- set ignore = rows.append(row) -%}
{%- endfor -%}
{%- set parties = rows | map(attribute="party") | unique | list -%}
{%- set party_type = filters.party_type or (rows[0].party_type if rows else ("Supplier" if payable else "Customer")) -%}
{%- set single = parties | length == 1 -%}
{%- set limits = (filters.range or "").split(",") | map("trim") | select | list if filters.range else [filters.range1, filters.range2, filters.range3, filters.range4] | select | map("string") | list -%}
{%- set limits = limits or ["30", "60", "90", "120"] -%}
{%- set labels = [_("Not Due")] -%}
{%- set low = namespace(value=0) -%}
{%- for limit in limits -%}
	{%- set ignore = labels.append(low.value ~ "-" ~ limit) -%}
	{%- set low.value = (limit | int) + 1 -%}
{%- endfor -%}
{%- set ignore = labels.append(_("{0} and above").format(low.value)) -%}
{%- set title = _("Bill-wise Pending") -%}
{%- set period = _("As on {0}").format(rp.date(filters.report_date)) -%}
{{ rp.styles() }}
<div class="rpf">
	{%- if show_company %}{{ rp.company_header(filters.company) }}{% endif %}
	{%- if single %}
	{{ rp.head(title, period, rp.party_name(party_type, parties[0]), rp.party_meta(party_type, parties[0])) }}
	{%- else %}
	{{ rp.head(title, period) }}
	{%- endif %}
	<table class="rpf-grid">
		<colgroup><col style="width: 80px"><col><col style="width: 80px"><col style="width: 74px"><col style="width: 128px"><col style="width: 128px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Reference No.") }}</th>
				<th>{{ _("Due On") }}</th>
				<th class="num">{{ _("Overdue") if by_due_date else _("Age") }}</th>
				<th class="num">{{ _("Bill Amount") }}</th>
				<th class="num">{{ _("Pending Amount") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for party in parties %}
			{%- set party_rows = rows | selectattr("party", "equalto", party) | list %}
			{%- if not single %}
			<tr class="group">
				<td colspan="3">{{ (party_rows[0].supplier_name or party_rows[0].customer_name or party) | e }} <span class="muted regular">· {{ (_("{0} bill") if party_rows | length == 1 else _("{0} bills")).format(party_rows | length) }}</span></td>
				<td></td>
				<td></td>
				<td class="num">{{ rp.drcr(sign * (party_rows | map(attribute="outstanding") | map("float") | sum)) }}</td>
			</tr>
			{%- endif %}
			{%- for row in party_rows %}
			{%- set amount = row.invoiced or row.credit_note or row.paid or row.outstanding | abs %}
			<tr>
				<td class="nowrap">{{ rp.date(row.posting_date) }}</td>
				<td>
					{{ (row.bill_no or row.voucher_no) | e }}
					{%- if row.bill_no %} <span class="muted">· {{ row.voucher_no | e }}</span>{% endif %}
				</td>
				<td class="nowrap">{{ rp.date(row.due_date) }}</td>
				<td class="num {{ 'danger' if row.outstanding > 0 and row.age > 90 and by_due_date else '' }}">
					{%- if row.outstanding < 0 %}
					{%- elif not by_due_date or row.age > 0 %}{{ row.age }} {{ _("days") }}
					{%- else %}<span class="muted">{{ _("Not due") }}</span>{% endif -%}
				</td>
				<td class="num muted">{{ rp.drcr(sign * (amount if row.outstanding > 0 else -amount)) }}</td>
				<td class="num">{{ rp.drcr(sign * row.outstanding) }}</td>
			</tr>
			{%- endfor %}
			{%- else %}
			<tr><td colspan="6" class="rpf-empty">{{ _("No pending bills") }}</td></tr>
			{%- endfor %}
			{%- if rows %}
			<tr class="total">
				<td></td>
				<td>{{ _("Total") }}</td>
				<td></td>
				<td></td>
				<td></td>
				<td class="num"><span class="double">{{ rp.drcr(sign * (rows | map(attribute="outstanding") | map("float") | sum)) }}</span></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{%- if rows and by_due_date %}
	<table class="rpf-buckets">
		<tr>
			{%- for label in labels %}
			{%- set bucket = rows | map(attribute="range" ~ loop.index0) | map("float") | sum %}
			<td>
				<div class="rpf-label">{{ label | e }}</div>
				<div class="rpf-value {{ 'danger' if bucket and loop.index0 >= 4 else '' }}">{{ rp.money(bucket | abs) if bucket else "–" }}</div>
			</td>
			{%- endfor %}
		</tr>
	</table>
	{%- endif %}
	{%- if single and rows %}
	{%- set balance = rows | map(attribute="outstanding") | map("float") | sum %}
	<div class="rpf-box">
		<div class="rpf-label">
			{%- if (balance > 0) == payable %}{{ _("Balance payable to you as on {0}").format(rp.date(filters.report_date)) }}
			{%- else %}{{ _("Balance due from you as on {0}").format(rp.date(filters.report_date)) }}{% endif -%}
		</div>
		<div class="rpf-value rpf-value-lg">{{ frappe.utils.fmt_money(balance | abs, currency=rows[0].currency) }}</div>
		<div class="note">{{ frappe.utils.money_in_words(balance | abs, rows[0].currency) }}</div>
	</div>
	{%- endif %}
	{{ rp.footnote() }}
</div>

{%
	const report_columns = report
		.get_columns_for_print()
		.filter(col => !col.hidden);

	if (report_columns.length > 8) {
		frappe.throw(
			__("Too many columns. Export the report and print it using a spreadsheet application.")
		);
	}
%}

<style>
	body, html {
		margin-top: 10px;
		padding: 0;
		width: 100%;
		height: auto;
		font-family: Inter, sans-serif;
		font-size: 14px;
		line-height: 21px;
		color: #171717;
	}

	.title-letter-spacing {
		font-size: 14px;
		font-weight: 600;
		color: #171717;
	}

	.financial-statements-important td {
		font-weight: bold;
	}

	.financial-statements-blank-row td {
		height: 43px;
	}

	.report-meta {
		margin: 10px 0 14px;
		padding: 8px 10px;
		display: flex;
		justify-content: space-between;
		align-items: flex-start;
		gap: 12px;
		font-size: 14px;
		color: #171717;
	}

	.report-meta .left,
	.report-meta .right {
		display: flex;
		flex-direction: column;
	}

	.report-meta strong {
		color: #7c7c7c;
		font-weight: 500;
	}

	.report-subtitle {
		margin: 10px 0 14px;
	}

	.text-center {
		text-align: center;
	}

	.text-right {
		text-align: right;
		font-variant-numeric: tabular-nums;
		white-space: nowrap;
		overflow: hidden;
		text-overflow: ellipsis;
	}

	.text-left {
		text-align: left;
	}

	.text-bold {
		font-weight: 700;
	}

	.text-muted {
		color: #7c7c7c;
	}

	.report-table table {
		width: 100%;
		table-layout: fixed;
		border-collapse: separate;
		border-spacing: 0;
	}

	.report-table th,
	.report-table td {
		padding: 6px 8px;
		font-size: 14px;
		border-bottom: 1px solid #ededed;
	}

	.report-table thead th {
		background: #f8f8f8;
		font-weight: 500;
		color: #7c7c7c;
		border-top: 1px solid #ededed;
		border-bottom: 1px solid #ededed;
	}

	.report-table tbody td.text-left {
		vertical-align: top;
		word-wrap: break-word;
	}

	.report-table thead tr:first-child th:first-child {
		border-left: 1px solid #ededed;
		border-top-left-radius: 10px;
		border-bottom-left-radius: 10px;
	}

	.report-table thead tr:first-child th:last-child {
		border-right: 1px solid #ededed;
		border-top-right-radius: 10px;
		border-bottom-right-radius: 10px;
	}

	.report-table tbody tr:last-child td {
		border-bottom: none;
	}

	.report-table tbody tr {
		height: 43px;
	}

	@media print {
		@page {
			size: A4;
			margin-top: 10mm;
		}

		thead {
			display: table-header-group;
		}

		tr {
			page-break-inside: avoid;
		}
	}
</style>

<div>

	<div class="text-center" style="margin-bottom: 12px;">
		<div class="title-letter-spacing">
			{%= __(report.report_name) %}
		</div>
	</div>

    {% if (subtitle && subtitle.trim()) { %}
        <div class="report-subtitle">
            {{ subtitle }}
        </div>
    {% } else { %}
        <div class="report-meta">
            <div class="left">
                <div>
                    <strong>{%= __("Company") %}:</strong> {%= filters.company %}
                </div>
                <div>
                    <strong>{%= __("Currency") %}:</strong>
                    {%= filters.presentation_currency || erpnext.get_currency(filters.company) %}
                </div>
            </div>

            <div class="right text-right">
                <div>
                    <strong>{%= __("From Date") %}:</strong>
                    {%= frappe.datetime.str_to_user(filters.from_date) %}
                </div>
                <div>
                    <strong>{%= __("To Date") %}:</strong>
                    {%= frappe.datetime.str_to_user(filters.to_date) %}
                </div>
            </div>
        </div>
    {% } %}

	<div class="report-table">
    	<table>
    		<thead>
    			<tr>
    				{% for (let i = 0, l = report_columns.length; i < l; i++) { %}
    					{%
    						const col = report_columns[i];
    						const align = i === 0 ? "text-left" : "text-right";
    						const styling = i === 0 ? "" : "width: 9em";
    					%}
    					<th class="{%= align %}" style= "{%= styling%}">
    						{%= col.label %}
    					</th>
    				{% } %}
    			</tr>
    		</thead>

    		<tbody>
    			{% for (let j = 0, k = data.length; j < k; j++) { %}
    				{%
    					const row = data[j];

    					let row_class = "";
    					if (!(row.parent_account || row.parent_section)) {
    						row_class = "financial-statements-important";
    					}
    					if (!(row.account_name || row.section)) {
    						row_class += " financial-statements-blank-row";
    					}
    				%}

    				<tr class="{%= row_class %}">
    					{% for (let i = 0, l = report_columns.length; i < l; i++) { %}
    						{%
    							const col = report_columns[i];
    							const value = row[col.fieldname];
    							const align = i === 0 ? "text-left" : "text-right";
    						%}

    						<td class="{%= align %}">
    							{% if (i === 0) { %}
    								<span style="padding-left: {%= cint(row.indent) * 2 %}em">
    									{%= String(row.account_name || row.section || "").replace(/^['"]|['"]$/g, "") %}
    								</span>
    							{% } else if (!is_null(value)) { %}
    								{%= frappe.format(value, col, {}, row) %}
    							{% } %}
    						</td>
    					{% } %}
    				</tr>
    			{% } %}
    		</tbody>
    	</table>
    </div>

	<p class="text-right text-muted">
		{%= __("Printed on {0}", [
			frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string())
		]) %}
	</p>

</div>

